#define _XOPEN_SOURCE 700

#include <stdlib.h>
#include <string.h>

#include "json.h"
#include "util.h"

static int hex4(const char *s, unsigned long *out)
{
	unsigned long v = 0;
	int i;

	for (i = 0; i < 4; i++) {
		v <<= 4;
		if (s[i] >= '0' && s[i] <= '9')
			v |= (unsigned long)(s[i] - '0');
		else if (s[i] >= 'a' && s[i] <= 'f')
			v |= (unsigned long)(s[i] - 'a' + 10);
		else if (s[i] >= 'A' && s[i] <= 'F')
			v |= (unsigned long)(s[i] - 'A' + 10);
		else
			return 0;
	}
	*out = v;
	return 1;
}

static size_t utf8_put(char *out, unsigned long cp)
{
	if (cp < 0x80) {
		out[0] = (char)cp;
		return 1;
	}
	if (cp < 0x800) {
		out[0] = (char)(0xc0 | cp >> 6);
		out[1] = (char)(0x80 | (cp & 0x3f));
		return 2;
	}
	if (cp < 0x10000) {
		out[0] = (char)(0xe0 | cp >> 12);
		out[1] = (char)(0x80 | (cp >> 6 & 0x3f));
		out[2] = (char)(0x80 | (cp & 0x3f));
		return 3;
	}
	out[0] = (char)(0xf0 | cp >> 18);
	out[1] = (char)(0x80 | (cp >> 12 & 0x3f));
	out[2] = (char)(0x80 | (cp >> 6 & 0x3f));
	out[3] = (char)(0x80 | (cp & 0x3f));
	return 4;
}

/*
 * Decodes the body of a JSON string (without the quotes). A lone surrogate
 * has no UTF-8 form and becomes U+FFFD. Returns NULL for invalid input.
 */
char *json_decode_string(const char *s, size_t len)
{
	const char *end = s + len;
	unsigned long cp, lo;
	char *out;
	size_t n = 0;

	/* No escape grows: \uXXXX (6 bytes) gives at most 3, a pair at most 4. */
	out = xmalloc(len + 1);
	while (s < end) {
		if ((unsigned char)*s < 0x20 || *s == '"')
			goto invalid;
		if (*s != '\\') {
			out[n++] = *s++;
			continue;
		}
		if (end - s < 2)
			goto invalid;
		switch (s[1]) {
		case '"':
		case '\\':
		case '/':
			out[n++] = s[1];
			s += 2;
			continue;
		case 'b':
			out[n++] = '\b';
			s += 2;
			continue;
		case 'f':
			out[n++] = '\f';
			s += 2;
			continue;
		case 'n':
			out[n++] = '\n';
			s += 2;
			continue;
		case 'r':
			out[n++] = '\r';
			s += 2;
			continue;
		case 't':
			out[n++] = '\t';
			s += 2;
			continue;
		case 'u':
			break;
		default:
			goto invalid;
		}
		if (end - s < 6 || !hex4(s + 2, &cp))
			goto invalid;
		s += 6;
		if (cp >= 0xd800 && cp <= 0xdbff && end - s >= 6 &&
		    s[0] == '\\' && s[1] == 'u' && hex4(s + 2, &lo) &&
		    lo >= 0xdc00 && lo <= 0xdfff) {
			cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
			s += 6;
		} else if (cp >= 0xd800 && cp <= 0xdfff) {
			cp = 0xfffd;
		}
		n += utf8_put(out + n, cp);
	}
	out[n] = '\0';
	return out;
invalid:
	free(out);
	return NULL;
}

static size_t skip_space(const char *s, size_t len, size_t i)
{
	while (i < len && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' ||
	    s[i] == '\r'))
		i++;
	return i;
}

/*
 * Each scanner below starts at index i and returns the index just past the
 * token, or 0 when it is invalid; a valid token never ends at index 0.
 */
static size_t scan_string(const char *s, size_t len, size_t i)
{
	unsigned long cp;

	for (i++; i < len; i++) {
		if (s[i] == '"')
			return i + 1;
		if ((unsigned char)s[i] < 0x20)
			return 0;
		if (s[i] != '\\')
			continue;
		if (++i >= len)
			return 0;
		switch (s[i]) {
		case '"':
		case '\\':
		case '/':
		case 'b':
		case 'f':
		case 'n':
		case 'r':
		case 't':
			break;
		case 'u':
			if (len - i < 5 || !hex4(s + i + 1, &cp))
				return 0;
			i += 4;
			break;
		default:
			return 0;
		}
	}
	return 0;
}

static int is_digit(const char *s, size_t len, size_t i)
{
	return i < len && s[i] >= '0' && s[i] <= '9';
}

static size_t scan_number(const char *s, size_t len, size_t i)
{
	if (i < len && s[i] == '-')
		i++;
	if (!is_digit(s, len, i))
		return 0;
	if (s[i] == '0')
		i++;
	else
		while (is_digit(s, len, i))
			i++;
	if (i < len && s[i] == '.') {
		if (!is_digit(s, len, ++i))
			return 0;
		while (is_digit(s, len, i))
			i++;
	}
	if (i < len && (s[i] == 'e' || s[i] == 'E')) {
		i++;
		if (i < len && (s[i] == '+' || s[i] == '-'))
			i++;
		if (!is_digit(s, len, i))
			return 0;
		while (is_digit(s, len, i))
			i++;
	}
	return i;
}

static size_t scan_literal(const char *s, size_t len, size_t i)
{
	static const char *const words[] = { "true", "false", "null" };
	size_t k, n;

	for (k = 0; k < sizeof words / sizeof words[0]; k++) {
		n = strlen(words[k]);
		if (len - i >= n && memcmp(s + i, words[k], n) == 0)
			return i + n;
	}
	return 0;
}

struct frame {
	char open;
	size_t start;
};

/*
 * Walks a complete JSON text (RFC 8259) and calls visit for every key and
 * value: scalars where they stand, containers when they close. Nesting is
 * limited only by memory. Returns 0 for valid JSON and -1 otherwise; the
 * visits made before the error was found are then meaningless.
 */
int json_scan(const char *text, size_t len, json_visit visit, void *ctx)
{
	struct frame *frames = NULL;
	struct json_seg *path = NULL;
	struct json_token tok;
	size_t depth = 0, cap = 0, i, end;
	int ok = 0;

	i = skip_space(text, len, 0);
	for (;;) {
		/* A value starts at i. */
		if (i >= len)
			goto done;
		tok.is_key = 0;
		tok.start = i;
		switch (text[i]) {
		case '{':
		case '[':
			if (depth == cap) {
				cap = cap ? cap * 2 : 16;
				frames = xrealloc(frames, cap * sizeof *frames);
				path = xrealloc(path, cap * sizeof *path);
			}
			frames[depth].open = text[i];
			frames[depth].start = i;
			path[depth].key = NULL;
			path[depth].index = 0;
			depth++;
			i = skip_space(text, len, i + 1);
			if (i < len &&
			    text[i] == (frames[depth - 1].open == '{' ? '}' : ']'))
				goto close;
			if (frames[depth - 1].open == '[')
				continue;
			goto key;
		case '"':
			tok.kind = JSON_STRING;
			end = scan_string(text, len, i);
			break;
		case 't':
		case 'f':
		case 'n':
			tok.kind = JSON_LITERAL;
			end = scan_literal(text, len, i);
			break;
		default:
			tok.kind = JSON_NUMBER;
			end = scan_number(text, len, i);
			break;
		}
		if (end == 0)
			goto done;
		tok.end = end;
		tok.path = path;
		tok.depth = depth;
		visit(&tok, ctx);
		i = end;
		goto next;
	close:
		depth--;
		free(path[depth].key);
		path[depth].key = NULL;
		tok.kind = frames[depth].open == '{' ? JSON_OBJECT : JSON_ARRAY;
		tok.is_key = 0;
		tok.start = frames[depth].start;
		tok.end = i + 1;
		tok.path = path;
		tok.depth = depth;
		visit(&tok, ctx);
		i++;
	next:
		i = skip_space(text, len, i);
		if (depth == 0) {
			ok = i == len;
			goto done;
		}
		if (i >= len)
			goto done;
		if (frames[depth - 1].open == '[') {
			if (text[i] == ']')
				goto close;
			if (text[i] != ',')
				goto done;
			path[depth - 1].index++;
			i = skip_space(text, len, i + 1);
			continue;
		}
		if (text[i] == '}')
			goto close;
		if (text[i] != ',')
			goto done;
		i = skip_space(text, len, i + 1);
	key:
		if (i >= len || text[i] != '"' ||
		    (end = scan_string(text, len, i)) == 0)
			goto done;
		free(path[depth - 1].key);
		path[depth - 1].key = json_decode_string(text + i + 1, end - i - 2);
		tok.kind = JSON_STRING;
		tok.is_key = 1;
		tok.start = i;
		tok.end = end;
		tok.path = path;
		tok.depth = depth;
		visit(&tok, ctx);
		i = skip_space(text, len, end);
		if (i >= len || text[i] != ':')
			goto done;
		i = skip_space(text, len, i + 1);
	}
done:
	while (depth > 0)
		free(path[--depth].key);
	free(path);
	free(frames);
	return ok ? 0 : -1;
}

/*
 * The body of a JSON string for s, without the quotes, written the way
 * JSON.stringify writes it: only quotes, backslashes and control
 * characters are escaped, so "/" and UTF-8 stay as they are.
 */
char *json_encode_string(const char *s)
{
	static const char hex[] = "0123456789abcdef";
	const unsigned char *p;
	char *out, *q;
	size_t n = 0;

	for (p = (const unsigned char *)s; *p != '\0'; p++)
		n += *p < 0x20 ? 6 : *p == '"' || *p == '\\' ? 2 : 1;
	q = out = xmalloc(n + 1);
	for (p = (const unsigned char *)s; *p != '\0'; p++) {
		switch (*p) {
		case '"':
		case '\\':
			*q++ = '\\';
			*q++ = (char)*p;
			break;
		case '\b':
			*q++ = '\\';
			*q++ = 'b';
			break;
		case '\f':
			*q++ = '\\';
			*q++ = 'f';
			break;
		case '\n':
			*q++ = '\\';
			*q++ = 'n';
			break;
		case '\r':
			*q++ = '\\';
			*q++ = 'r';
			break;
		case '\t':
			*q++ = '\\';
			*q++ = 't';
			break;
		default:
			if (*p < 0x20) {
				memcpy(q, "\\u00", 4);
				q[4] = hex[*p >> 4];
				q[5] = hex[*p & 0xf];
				q += 6;
			} else {
				*q++ = (char)*p;
			}
			break;
		}
	}
	*q = '\0';
	return out;
}

struct top_find {
	const char *key;
	size_t start, end;
	int found;
};

static void find_top(const struct json_token *tok, void *ctx)
{
	struct top_find *f = ctx;

	if (tok->depth != 1 || tok->is_key || tok->path[0].key == NULL ||
	    strcmp(tok->path[0].key, f->key) != 0)
		return;
	/* The last duplicate wins, as in JSON.parse. */
	f->found = tok->kind == JSON_STRING;
	f->start = tok->start + 1;
	f->end = tok->end - 1;
}

/*
 * The value of a string field of the top-level object, or NULL when the
 * field is missing, is not a string, or the text is not a valid JSON
 * object. Nested fields with the same name are ignored.
 */
char *json_top_string(const char *text, const char *key)
{
	struct top_find f;

	f.key = key;
	f.found = 0;
	if (json_scan(text, strlen(text), find_top, &f) != 0 || !f.found)
		return NULL;
	return json_decode_string(text + f.start, f.end - f.start);
}
